using Microsoft.AspNetCore.Authorization;using Microsoft.AspNetCore.Mvc;using Microsoft.AspNetCore.Mvc.RazorPages;using Microsoft.EntityFrameworkCore;using OrcaFacil.Domain.Entities;using OrcaFacil.Persistence;
namespace OrcaFacil.Web.Pages.SuperAdmin.Clients;
[Authorize(Policy="SuperAdminOnly")] public sealed class DetailsModel(OrcaFacilDbContext db):PageModel{public View Client{get;private set;}=default!;public async Task<IActionResult> OnGetAsync(Guid id,CancellationToken ct){var since=DateTime.UtcNow.AddDays(-30);var row=await db.BusinessAccounts.AsNoTracking().Where(x=>x.Id==id&&!x.IsDeleted).Select(x=>new View(x.Id,x.DisplayName,x.DocumentNumber??"—",x.Email,x.Status.ToString(),x.CurrentPlanCode,x.FinancialStatus,x.ResponsibleName,$"{x.City}/{x.State}",db.AccountMembers.Count(m=>m.AccountId==x.Id&&!m.IsDeleted),db.AccountModuleSubscriptions.Count(s=>s.AccountId==x.Id&&!s.IsDeleted&&(s.Status==SaasModuleSubscriptionStatus.Active||s.Status==SaasModuleSubscriptionStatus.Trial)),db.AccountModuleUsageEvents.Count(e=>e.AccountId==x.Id&&e.OccurredAt>=since),db.AccountModuleSubscriptions.Where(s=>s.AccountId==x.Id&&!s.IsDeleted&&s.Status==SaasModuleSubscriptionStatus.Active).Sum(s=>(decimal?)(s.BillingPeriod==SaasBillingPeriod.Annual?s.ContractedPrice/12:s.ContractedPrice-s.DiscountAmount))??0)).SingleOrDefaultAsync(ct);if(row is null)return NotFound();Client=row;return Page();}public sealed record View(Guid Id,string Name,string Document,string Email,string Status,string Plan,string Financial,string? Responsible,string Location,int Users,int Modules,int Usage,decimal Mrr);}
